<?php $title='Bandeja de entrada'; require __DIR__.'/partials/top.php';$pdo=appDb();$tid=(int)$_SESSION['user']['tenant_id'];$convs=[];$agents=[];$channels=[];$categories=[];$selected=null;$messages=[];$selectedCategories=[];$followup=null;$notes=[];try{$q=$pdo->prepare("SELECT c.id,c.uuid,c.contact_id,c.assigned_user_id,c.unread_count,c.last_message_at,c.priority,ct.name contact_name,ct.phone,ct.avatar_url,ch.type channel_type,(SELECT body FROM messages m WHERE m.conversation_id=c.id ORDER BY m.sent_at DESC,m.id DESC LIMIT 1) last_body FROM conversations c JOIN contacts ct ON ct.id=c.contact_id JOIN channels ch ON ch.id=c.channel_id WHERE c.tenant_id=? AND c.status IN ('open','pending') ORDER BY COALESCE(c.last_message_at,c.created_at) DESC");$q->execute([$tid]);$convs=$q->fetchAll();$cid=(int)($_GET['conversation']??($convs[0]['id']??0));foreach($convs as $c)if((int)$c['id']===$cid)$selected=$c;if($selected){$q=$pdo->prepare('SELECT m.*,u.name sender_name FROM messages m LEFT JOIN users u ON u.id=m.sender_user_id WHERE m.tenant_id=? AND m.conversation_id=? ORDER BY m.sent_at,m.id');$q->execute([$tid,$cid]);$messages=$q->fetchAll();}$q=$pdo->prepare("SELECT u.id,u.name FROM users u JOIN tenant_users tu ON tu.user_id=u.id WHERE tu.tenant_id=? AND u.status='active' ORDER BY u.name");$q->execute([$tid]);$agents=$q->fetchAll();$q=$pdo->prepare("SELECT id,name,type,status FROM channels WHERE tenant_id=? ORDER BY name");$q->execute([$tid]);$channels=$q->fetchAll();$q=$pdo->prepare('SELECT id,name,color FROM contact_categories WHERE tenant_id=? AND active=1 ORDER BY name');$q->execute([$tid]);$categories=$q->fetchAll();if($selected){$q=$pdo->prepare('SELECT category_id FROM contact_category_map WHERE contact_id=?');$q->execute([$selected['contact_id']]);$selectedCategories=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$q=$pdo->prepare("SELECT follow_up_at,note FROM conversation_followups WHERE tenant_id=? AND conversation_id=? AND status='pending' ORDER BY id DESC LIMIT 1");$q->execute([$tid,$selected['id']]);$followup=$q->fetch()?:null;$q=$pdo->prepare('SELECT cn.body,cn.created_at,u.name FROM conversation_notes cn JOIN users u ON u.id=cn.user_id WHERE cn.tenant_id=? AND cn.conversation_id=? ORDER BY cn.id DESC LIMIT 5');$q->execute([$tid,$selected['id']]);$notes=$q->fetchAll();}}catch(Throwable $e){} ?>
<div class="inbox-layout"><section class="panel conv-list"><div class="panel-head"><div><b>Conversaciones</b><small><?=count($convs)?> abiertas</small></div><div class="head-actions"><button class="soft" data-open="newConversationModal"><i class="fa-solid fa-plus"></i> Nueva</button><button class="soft"><i class="fa-solid fa-filter"></i> Filtros</button></div></div><div class="search-wrap inbox-search"><i class="fa-solid fa-magnifying-glass"></i><input class="list-search" placeholder="Buscar cliente, teléfono o mensaje"><button class="clear-search" hidden><i class="fa-solid fa-xmark"></i></button></div><div class="conversation-scroll"><?php if(!$convs):?><div class="empty-compact"><i class="fa-regular fa-comments"></i><b>Sin conversaciones</b><span>Los mensajes reales aparecerán aquí.</span></div><?php else:foreach($convs as $c):?><a class="conversation searchable <?=($selected&&$selected['id']===$c['id'])?'active':''?>" href="?page=inbox&conversation=<?=$c['id']?>"><span class="avatar"><?=htmlspecialchars(strtoupper(substr($c['contact_name']?:'C',0,1)))?></span><div><b><?=htmlspecialchars($c['contact_name']?:'Contacto')?></b><p><?=htmlspecialchars($c['last_body']?:'Sin mensajes todavía')?></p></div><small><?=htmlspecialchars($c['channel_type'])?></small></a><?php endforeach;endif?></div></section>
<section class="panel chat"><?php if(!$selected):?><div class="empty-chat"><i class="fa-regular fa-comments"></i><h2>Selecciona una conversación</h2><p>Cuando existan conversaciones podrás responder, adjuntar archivos, usar emojis y pedir ayuda a NIVO.</p></div><?php else:?><div class="chat-head"><div><b><?=htmlspecialchars($selected['contact_name']?:'Contacto')?></b><small><?=htmlspecialchars(ucfirst($selected['channel_type']).' · '.($selected['phone']?:''))?></small></div><div class="head-actions"><button class="soft" id="autoAssignBtn" data-conversation="<?=$selected['id']?>"><i class="fa-solid fa-shuffle"></i> Asignación automática</button><button class="soft" data-open="assignModal"><i class="fa-solid fa-user-check"></i> Asignar</button></div></div><div class="messages" id="messages"><?php foreach($messages as $m):?><div class="message-wrap <?=$m['direction']==='out'?'out':'in'?>"><?php if($m['direction']==='out' && !empty($m['sender_name'])):?><b class="message-sender"><?=htmlspecialchars(mb_strtoupper($m['sender_name'].' · '.$company))?></b><?php elseif(($m['sender_type']??'')==='bot'):?><b class="message-sender"><?=htmlspecialchars('NIVO · '.mb_strtoupper($company))?></b><?php endif?><p class="<?=$m['direction']==='out'?'me':'them'?>"><?=nl2br(htmlspecialchars($m['body']??''))?></p><?php $media=json_decode($m['media_json']??'[]',true)?:[];foreach($media as $file):?><a class="chat-attachment" href="<?=htmlspecialchars($file['url'])?>" target="_blank"><i class="fa-solid fa-paperclip"></i><?=htmlspecialchars($file['name']??'Adjunto')?></a><?php endforeach?></div><?php endforeach?></div><form class="composer pro-composer" id="messageForm"><input type="hidden" name="action" value="message_send"><input type="hidden" name="conversation_id" value="<?=$selected['id']?>"><div class="composer-tools"><button type="button" title="Emoji" id="emojiBtn"><i class="fa-regular fa-face-smile"></i></button><button type="button" title="Adjuntar" id="attachBtn"><i class="fa-solid fa-paperclip"></i></button><button type="button" title="Respuesta rápida"><i class="fa-solid fa-bolt"></i></button><button type="button" title="Pedir ayuda a NIVO" id="nivoAssist"><i class="fa-solid fa-wand-magic-sparkles"></i> NIVO</button><input type="file" id="chatFile" multiple hidden accept="image/*,video/*,audio/*,.pdf,.doc,.docx,.xls,.xlsx,.txt"></div><div class="attachment-preview" id="attachmentPreview"></div><div class="composer-line"><textarea name="body" id="messageInput" placeholder="Escribe un mensaje…" rows="1"></textarea><button class="primary"><i class="fa-solid fa-paper-plane"></i><span>Enviar</span></button></div><div class="emoji-picker" id="emojiPicker" hidden>😀 😃 😄 😊 👍 🙏 ❤️ 🎉 😂 😍 😢 😎 👋 ✅ 📎 🔥</div></form><?php endif?></section>
<section class="panel info"><?php if($selected):?><div class="info-title"><b>Información del contacto</b><span class="realtime-dot" title="Actualización en tiempo real"></span></div><div class="profile"><span class="avatar big"><?=htmlspecialchars(strtoupper(substr($selected['contact_name']?:'C',0,1)))?></span><h3><?=htmlspecialchars($selected['contact_name']?:'Contacto')?></h3><small><?=htmlspecialchars($selected['phone']?:'Sin teléfono')?></small></div>
<form id="contactProfileForm" class="info-form"><input type="hidden" name="action" value="contact_update"><input type="hidden" name="contact_id" value="<?=$selected['contact_id']?>"><input type="hidden" name="conversation_id" value="<?=$selected['id']?>"><div class="field"><label>Nombre</label><input name="name" value="<?=htmlspecialchars($selected['contact_name']??'')?>" required></div><div class="field"><label>WhatsApp / teléfono</label><input name="phone" value="<?=htmlspecialchars($selected['phone']??'')?>" placeholder="+504…"></div><div class="field"><label>Prioridad</label><select name="priority" class="select2"><option value="low" <?=$selected['priority']==='low'?'selected':''?>>Baja</option><option value="normal" <?=$selected['priority']==='normal'?'selected':''?>>Normal</option><option value="high" <?=$selected['priority']==='high'?'selected':''?>>Alta</option><option value="urgent" <?=$selected['priority']==='urgent'?'selected':''?>>Urgente</option></select></div><button class="soft wide"><i class="fa-solid fa-floppy-disk"></i> Guardar contacto</button></form>
<div class="info-block"><div class="info-block-head"><b>Categorías</b><button type="button" class="icon-mini" data-open="categoryModal" title="Nueva categoría"><i class="fa-solid fa-plus"></i></button></div><form id="contactCategoriesForm"><input type="hidden" name="action" value="contact_categories_save"><input type="hidden" name="contact_id" value="<?=$selected['contact_id']?>"><div class="tag-checks"><?php if(!$categories):?><small class="field-help">Crea categorías como Cliente potencial, Soporte, VIP o Seguimiento.</small><?php endif?><?php foreach($categories as $cat):?><label class="tag-check"><input type="checkbox" name="categories[]" value="<?=$cat['id']?>" <?=in_array((int)$cat['id'],$selectedCategories,true)?'checked':''?>><span><?=htmlspecialchars($cat['name'])?></span></label><?php endforeach?></div><button class="soft wide"><i class="fa-solid fa-tags"></i> Guardar categorías</button></form></div>
<div class="info-block"><b>Seguimiento</b><form id="followupForm"><input type="hidden" name="action" value="followup_save"><input type="hidden" name="conversation_id" value="<?=$selected['id']?>"><input type="datetime-local" name="follow_up_at" value="<?=$followup?htmlspecialchars(date('Y-m-d\TH:i',strtotime($followup['follow_up_at']))):''?>" required><input name="follow_up_note" value="<?=htmlspecialchars($followup['note']??'')?>" placeholder="Motivo del seguimiento"><button class="soft wide"><i class="fa-solid fa-bell"></i> Programar</button></form></div>
<div class="info-block"><b>Nota interna</b><form id="noteForm"><input type="hidden" name="action" value="conversation_note_add"><input type="hidden" name="conversation_id" value="<?=$selected['id']?>"><textarea name="note" rows="2" placeholder="Solo visible para el equipo"></textarea><button class="soft wide"><i class="fa-solid fa-note-sticky"></i> Agregar nota</button></form><?php foreach($notes as $n):?><div class="mini-note"><b><?=htmlspecialchars($n['name'])?></b><span><?=htmlspecialchars($n['body'])?></span></div><?php endforeach?></div>
