<?php if($selected):?><div class="modal-shell" id="assignModal"><div class="modal-card small-modal"><div class="modal-head"><div><b>Asignar conversación</b><small>Selecciona un usuario activo.</small></div><button class="modal-close"><i class="fa-solid fa-xmark"></i></button></div><form id="assignForm"><input type="hidden" name="action" value="conversation_assign"><input type="hidden" name="conversation_id" value="<?=$selected['id']?>"><div class="field"><label>Usuario</label><select name="user_id" class="select2" required><option value="">Seleccionar…</option><?php foreach($agents as $a):?><option value="<?=$a['id']?>" <?=$selected['assigned_user_id']==$a['id']?'selected':''?>><?=htmlspecialchars($a['name'])?></option><?php endforeach?></select></div><div class="modal-actions"><button type="button" class="soft modal-close"><i class="fa-solid fa-xmark"></i> Cancelar</button><button class="primary"><i class="fa-solid fa-user-check"></i> Asignar</button></div></form></div></div><?php endif?>
